import { HttpResponse, http } from 'msw';

import { env } from '@/config/env';

import { db, persistDb } from '../db';
import { networkDelay, requireAuth } from '../utils';

type UpdateTeamBody = {
  name: string;
};

export const teamsHandlers = [
  http.get(`${env.API_URL}/teams`, async () => {
    await networkDelay();

    try {
      const result = db.team.getAll();
      return HttpResponse.json({ data: result });
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),

  http.patch(`${env.API_URL}/teams/:teamId`, async ({ request, params, cookies }) => {
    await networkDelay();

    try {
      const { user, error } = requireAuth(cookies);
      if (error) {
        return HttpResponse.json({ message: error }, { status: 401 });
      }
      if (user?.role !== 'ADMIN') {
        return HttpResponse.json(
          { message: 'Only admins can rename the team' },
          { status: 403 },
        );
      }

      const teamId = params.teamId as string;
      if (teamId !== user.teamId) {
        return HttpResponse.json({ message: 'Team not found' }, { status: 404 });
      }

      const { name } = (await request.json()) as UpdateTeamBody;
      if (typeof name !== 'string' || name.trim() === '') {
        return HttpResponse.json(
          { message: 'The team name is required' },
          { status: 400 },
        );
      }

      const result = db.team.update({
        where: {
          id: {
            equals: teamId,
          },
        },
        data: { name: name.trim() },
      });
      await persistDb('team');
      return HttpResponse.json(result);
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),
];
EOF
