import { Pen } from 'lucide-react';

import { Button } from '@/components/ui/button';
import { Form, FormDrawer, Input } from '@/components/ui/form';
import { useNotifications } from '@/components/ui/notifications';
import { Authorization, ROLES } from '@/lib/authorization';

import { updateTeamInputSchema, useUpdateTeam } from '../api/update-team';

type UpdateTeamProps = {
  teamId: string;
  teamName: string;
};

export const UpdateTeam = ({ teamId, teamName }: UpdateTeamProps) => {
  const { addNotification } = useNotifications();
  const updateTeamMutation = useUpdateTeam({
    mutationConfig: {
      onSuccess: () => {
        addNotification({
          type: 'success',
          title: 'Team Renamed',
        });
      },
    },
  });

  return (
    <Authorization allowedRoles={[ROLES.ADMIN]}>
      <FormDrawer
        isDone={updateTeamMutation.isSuccess}
        triggerButton={
          <Button icon={<Pen className="size-4" />} size="sm">
            Rename Team
          </Button>
        }
        title="Rename Team"
        submitButton={
          <Button
            form="update-team"
            type="submit"
            size="sm"
            isLoading={updateTeamMutation.isPending}
          >
            Submit
          </Button>
        }
      >
        <Form
          id="update-team"
          onSubmit={(values) => {
            updateTeamMutation.mutate({ data: values, teamId });
          }}
          options={{
            defaultValues: {
              name: teamName,
            },
          }}
          schema={updateTeamInputSchema}
        >
          {({ register, formState }) => (
            <Input
              label="Team Name"
              error={formState.errors['name']}
              registration={register('name')}
            />
          )}
        </Form>
      </FormDrawer>
    </Authorization>
  );
};
